basic-example:
import { useState } from 'react';
import { DsTimePicker } from '@primasoftllc/design-system';

export function Example() {
  const [value, setValue] = useState('09:00');
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsTimePicker label="Начало смены" value={value} onChange={setValue} hint="Время в часовом поясе расписания: Europe/Minsk."/>
    <output aria-live="polite">Выбрано: {value || 'не указано'}</output>
  </div>;
}

form-validation:
import { useState } from 'react';
import { DsTimePicker, DsButton } from '@primasoftllc/design-system';

export function Example() {
  const [result, setResult] = useState('');
  return <form style={{display:'flex',flexDirection:'column',gap:16}} onSubmit={event => {
    event.preventDefault();
    setResult('Сохранено: ' + new FormData(event.currentTarget).get('scheduled'));
  }} onReset={() => setResult('')}>
    <DsTimePicker label="Начало смены" name="scheduled" defaultValue="09:00"
      required min="08:00" max="18:00"
      hint="Допустимый интервал: 08:00 — 18:00."/>
    <div style={{display:'flex',flexWrap:'wrap',gap:8}}>
      <DsButton type="submit">Сохранить</DsButton>
      <DsButton type="reset" tone="secondary">Сбросить</DsButton>
    </div>
    <span role="status">{result}</span>
  </form>;
}

field-states:
import { DsTimePicker } from '@primasoftllc/design-system';

export function Example() {
  return <div style={{display:'flex',flexDirection:'column',gap:16}}>
    <DsTimePicker label="Подтверждённое значение" defaultValue="09:00" readOnly hint="Изменение доступно после отмены подтверждения."/>
    <DsTimePicker label="Недоступное значение" defaultValue="09:00" disabled hint="Недостаточно прав для изменения."/>
    <DsTimePicker label="Проверка сервером" defaultValue="09:00" error="Это время уже занято. Выберите другое."/>
  </div>;
}
